with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__USER_ID))) as HUB_PARTY_HK
        , EMP_NO as EMPLOYEE_NUMBER
        , cast(null as varchar) as MONTHLY_SALARY_AMOUNT
        , 'BA_HCP_DT_PREMIUM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_dt_premium') }}
    where (nullif(trim(USER_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_ID))) as HUB_PARTY_HK
        , cast(null as varchar) as EMPLOYEE_NUMBER
        , MONTHLY_SALARY as MONTHLY_SALARY_AMOUNT
        , 'BJAZ_HM_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_dtls') }}
    where (nullif(trim(MEMBER_ID),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EMPLOYEE_NUMBER end) as EMPLOYEE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MONTHLY_SALARY_AMOUNT end) as MONTHLY_SALARY_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when EMPLOYEE_NUMBER is not null or MONTHLY_SALARY_AMOUNT is not null
                     then md5(upper(coalesce(cast(EMPLOYEE_NUMBER as varchar), '') || '|' || coalesce(cast(MONTHLY_SALARY_AMOUNT as varchar), '')))
                end as SAT_PARTY_EMPLOYMENT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_EMPLOYMENT_HASHDIFF is not null
